import{c as o,Q as t,j as r,m as s}from"./chunks/framework.DOi4mjdC.js";const n="/assets/Vector%E7%BC%96%E7%A8%8B%E8%8C%83%E5%BC%8F%E6%8C%87%E4%BB%A4%E9%98%9F%E5%88%97%E7%A4%BA%E4%BE%8B.UNwmTkpC.png",a="/assets/%E5%9B%BE1-AI-Core%E5%86%85%E9%83%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%E6%9E%B6%E6%9E%84%E6%8A%BD%E8%B1%A1%E7%A4%BA%E6%84%8F%E5%9B%BE-28.BFwD0Csd.png",l="/assets/%E5%9B%BE1-AI-Core%E5%86%85%E9%83%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%E6%9E%B6%E6%9E%84%E6%8A%BD%E8%B1%A1%E7%A4%BA%E6%84%8F%E5%9B%BE-29.QWSWOGY8.png",i="/assets/Iterate_flase-30.Cz4S22Cy.png",Q=JSON.parse('{"title":"TPipe-TQue编程原理介绍","description":"","frontmatter":{},"headers":[{"level":1,"title":"TPipe-TQue编程原理介绍","slug":"tpipe-tque编程原理介绍"},{"level":2,"title":"设计思想渊源：从经典队列管道到Ascend C TPipe-TQue编程模型","slug":"设计思想渊源从经典队列管道到ascend-c-tpipe-tque编程模型"},{"level":2,"title":"TPipe-TQue框架核心定义与编程原理","slug":"tpipe-tque框架核心定义与编程原理"},{"level":2,"title":"数据依赖与同步机制：双API的协同工作","slug":"数据依赖与同步机制双api的协同工作"},{"level":3,"title":"生产者‑消费者同步：EnQue/DeQue解决写后读冲突","slug":"生产者消费者同步enquedeque解决写后读冲突"},{"level":3,"title":"内存生命周期管理：AllocTensor/FreeTensor解决读后写冲突","slug":"内存生命周期管理alloctensorfreetensor解决读后写冲突"},{"level":2,"title":"小结","slug":"小结"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程原理.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程原理.md"}'),c={name:"guide/编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程原理.md"};function d(p,e,u,g,T,E){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="tpipe-tque编程原理介绍" tabindex="-1">TPipe-TQue编程原理介绍 <a class="header-anchor" href="#tpipe-tque编程原理介绍" aria-label="Permalink to &quot;TPipe-TQue编程原理介绍&quot;">​</a></h1><h2 id="设计思想渊源-从经典队列管道到ascend-c-tpipe-tque编程模型" tabindex="-1">设计思想渊源：从经典队列管道到Ascend C TPipe-TQue编程模型 <a class="header-anchor" href="#设计思想渊源-从经典队列管道到ascend-c-tpipe-tque编程模型" aria-label="Permalink to &quot;设计思想渊源：从经典队列管道到Ascend C TPipe-TQue编程模型&quot;">​</a></h2><p>Ascend C编程模型的核心架构，深度承袭了传统C/C++并发编程中<strong>队列管道(Queue Pipeline)</strong> 的经典设计理念。在通用并发编程体系中，管道模式的核心价值在于任务解耦与流程结构化：将复杂计算任务拆分为多个独立、可并行执行的处理阶段（Stage），各阶段之间通过线程安全队列完成数据传递与消息同步。</p><p>这种<strong>阶段解耦、队列互联</strong>的架构，将原本无序的异步并发控制转化为逻辑清晰、可顺序理解的数据流，从根本上规避了显式锁和复杂同步带来的心智负担，降低了并行程序的设计、调试与维护成本。</p><p>面向AI Core的异构并行计算场景，Ascend C对经典队列流水线思想进行了适配与创新，构建了专属的<strong>TPipe-TQue并行编程模型</strong>。该模型由三大核心要素构成：可并行执行的处理阶段（Stage）、全局资源管理、跨阶段队列同步通信。同时，Ascend C将底层硬件同步指令与片上内存生命周期管理分别封装为<code>EnQue</code>/<code>DeQue</code>和<code>AllocTensor</code>/<code>FreeTensor</code>两组标准化接口，形成了一套轻量级、高可控、标准化的异构并行编程范式。</p><h2 id="tpipe-tque框架核心定义与编程原理" tabindex="-1">TPipe-TQue框架核心定义与编程原理 <a class="header-anchor" href="#tpipe-tque框架核心定义与编程原理" aria-label="Permalink to &quot;TPipe-TQue框架核心定义与编程原理&quot;">​</a></h2><p><strong>TPipe</strong>与<strong>TQue</strong>是支撑多Stage流水线并行运行的两大基础组件，二者职责分明、紧密协同：</p><ul><li><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TPipe.md" target="_blank" rel="noreferrer">TPipe</a></strong> 作为资源管理器，统一管理系统内存资源及用于同步的事件等；</li><li><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TQue.md" target="_blank" rel="noreferrer">TQue</a></strong> 作为队列，负责完成Stage任务间的同步与通信。</li></ul><p>在TPipe-TQue模型下，完整的算子计算流程被拆分为若干独立、可并行调度的Stage，每个Stage都遵循一套标准化的四步编程范式：</p><ol><li><strong>内存获取</strong>：通过<code>AllocTensor</code>主动申请片上临时内存，或通过<code>DeQue</code>从上游TQue获取已就绪的数据内存。</li><li><strong>计算执行</strong>：在获取的合法内存上完成核心计算、数据搬运或格式转换等操作。</li><li><strong>数据传递与同步</strong>：通过<code>EnQue</code>将结果数据推入下游TQue，同时触发同步信号，唤醒等待中的下游任务。</li><li><strong>内存释放</strong>：对于不再使用的内存，调用<code>FreeTensor</code>主动释放，并向硬件发出可覆写信号，供后续任务复用，提升片上内存利用率。</li></ol><p>该范式将复杂的异步并行调度及硬件同步，抽象为开发者熟悉的内存管理与队列操作。以Vector矢量计算为例，这些接口会被编译器转化为底层的指令序列，形成完整的指令流水线，如下图所示：</p><p><strong>图 1</strong> Vector编程范式指令队列示例<br><img src="'+n+'" alt="" title="Vector编程范式指令队列示例"></p><p>指令的生成、分发与执行遵循统一的异步流水线：</p><ol><li><strong>取指与解码</strong>：标量处理单元读取算子指令序列并进行解码。</li><li><strong>指令发射</strong>：标量单元将解码后的指令发射到对应执行单元的指令队列。</li><li><strong>并行执行</strong>：各执行单元独立、并行地从各自队列中取出指令并执行。</li></ol><p>在这种异步并行架构下，多单元、多Stage的并发执行会引入复杂的数据依赖，而这正是异构编程的核心难点。Ascend C通过两组成对的API，在底层精准植入<code>Set</code>/<code>Wait</code>硬件同步指令，以极低的性能代价解决了这一问题。</p><h2 id="数据依赖与同步机制-双api的协同工作" tabindex="-1">数据依赖与同步机制：双API的协同工作 <a class="header-anchor" href="#数据依赖与同步机制-双api的协同工作" aria-label="Permalink to &quot;数据依赖与同步机制：双API的协同工作&quot;">​</a></h2><p>异步并行计算中的核心数据依赖可归纳为两类：<strong>写后读（WAR，Write‑After‑Read）<strong>和</strong>读后写（RAW，Read‑After‑Write）</strong>。Ascend C针对性地提供了两套配对接口，构建起完整的并行同步闭环。</p><h3 id="生产者‐消费者同步-enque-deque解决写后读冲突" tabindex="-1">生产者‑消费者同步：EnQue/DeQue解决写后读冲突 <a class="header-anchor" href="#生产者‐消费者同步-enque-deque解决写后读冲突" aria-label="Permalink to &quot;生产者‑消费者同步：EnQue/DeQue解决写后读冲突&quot;">​</a></h3><p>写后读是典型的上下游依赖：上游生产者必须完成写入，下游消费者才能开始读取，否则将读到不完整或错误的数据。<code>EnQue</code>/<code>DeQue</code>用于确保这一严格的时序约束。</p><ul><li><strong>EnQue（生产者信号）</strong>：作为上游任务的收尾操作，调用后底层自动发射<code>Set</code>硬件同步指令，标记当前阶段写入已完成，并主动唤醒下游阻塞任务。</li><li><strong>DeQue（消费者等待）</strong>：作为下游任务的起始操作，调用后底层发射<code>Wait</code>同步指令，当前任务进入阻塞，直至收到上游<code>Set</code>信号，确保所需数据完全就绪后才执行读取。</li></ul><p><img src="'+a+'" alt=""></p><p>通过信号阻塞与唤醒的精准配合，该机制严格保证了<strong>先写后读</strong>的执行时序，从源头杜绝写后读冲突，确保跨Stage数据传输的完整无误。</p><h3 id="内存生命周期管理-alloctensor-freetensor解决读后写冲突" tabindex="-1">内存生命周期管理：AllocTensor/FreeTensor解决读后写冲突 <a class="header-anchor" href="#内存生命周期管理-alloctensor-freetensor解决读后写冲突" aria-label="Permalink to &quot;内存生命周期管理：AllocTensor/FreeTensor解决读后写冲突&quot;">​</a></h3><p>读后写冲突源于内存复用：一块片上内存若在仍有读者访问时就被新数据覆盖，将导致未读完数据丢失、计算出错。<code>AllocTensor</code>/<code>FreeTensor</code>通过管理内存生命周期来化解这一矛盾。</p><ul><li><strong>AllocTensor（申请与等待）</strong>：当任务申请某块内存时，底层发射<code>Wait</code>同步指令，持续等待该内存区域的所有读取操作彻底完成、进入可覆写状态，随后才分配内存并解除任务阻塞。</li><li><strong>FreeTensor（释放与通知）</strong>：当任务使用完毕并调用<code>FreeTensor</code>时，底层发射<code>Set</code>同步指令，通知硬件该内存已无读取依赖，可以安全释放或覆写，供后续任务复用。</li></ul><p><img src="'+l+'" alt=""></p><p>此机制精确管控每一块片上内存的读写状态与生命周期，确保覆写只发生在所有读操作完成之后，从底层消除读后写冲突，实现片上内存的高效、安全复用。</p><p><img src="'+i+'" alt=""></p><p>由此可见，异步并行程序所面临的复杂同步控制，在Ascend C中被转化为<code>EnQue</code>/<code>DeQue</code>、<code>AllocTensor</code>/<code>FreeTensor</code>这类开发者熟悉的资源操作。这种封装既保留了硬件级性能，又极大降低了编程与理解难度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>异构异步并行编程的核心挑战，在于对底层硬件同步信号的精确编排、多任务间的严格时序约束以及内存的安全管控。TPipe-TQue编程模型以经典队列管道思想为框架，通过<strong>TPipe管资源、TQue管通信</strong>的清晰分工，将晦涩的<code>Set</code>/<code>Wait</code>同步机制封装为直观的队列操作和内存管理接口。这一设计在充分释放AI Core异构并行算力、保障算子极致性能的同时，显著降低了开发与学习门槛，为Ascend C领域的高性能算子开发提供了简洁、可靠、标准化的编程范式。</p>',31)])])}const h=o(c,[["render",d]]);export{Q as __pageData,h as default};
